// Demo data seeding — populates a fresh (empty) database with a varied set of
// Islamic-themed memories (Qur'an, Arabic vocabulary, hadith, fiqh, seerah)
// spread across different "learned" dates and FSRS review histories, so the
// app is immediately populated and every page (Memory, Schedule, Review,
// Insights) has something real to show rather than empty states.
//
// Review history is generated by actually running memories through the real
// FSRS engine (schedule()) rather than hand-faking card state, so the
// resulting due dates, stability, difficulty and retention numbers are
// internally consistent with how the app would have produced them.

import { CardState, Rating, DEFAULT_SETTINGS } from "../core/types";
import type { Memory, ReviewLogEntry } from "../core/types";
import { createNewCard, schedule } from "../fsrs/engine";
import { dbPutMany, STORES } from "./database";
import { ensureCollection } from "./repository";
import { addDays } from "../core/dates";

function uid(prefix: string): string {
  return prefix + "_" + Date.now().toString(36) + Math.random().toString(36).slice(2, 10);
}

interface SeedSpec {
  content: string;
  prompt?: string;
  answer?: string;
  collection: string;
  tags: string[];
  learnedDaysAgo: number; // how many days ago this was learned
  // Simulated review ratings applied in order, spaced realistically, to
  // build up genuine FSRS state. Empty = still New.
  reviewRatings: Rating[];
}

