export async function seedDemoData(): Promise<void> {
  const now = new Date();
  const memories: Memory[] = [];
  const logs: ReviewLogEntry[] = [];

  for (const spec of SEED_SPECS) {
    const learnedAt = addDays(now, -spec.learnedDaysAgo);
    learnedAt.setHours(9, 0, 0, 0);

    let card = createNewCard(learnedAt);
    // Simulate the passage of time between the learn date and now, applying
    // each review at a sensible point along that span so ratings land on
    // distinct, plausible days rather than all at once.
    const now_ = now.getTime();
    const span = Math.max(1, spec.learnedDaysAgo);
    const memoryId = uid("mem");

    spec.reviewRatings.forEach((rating, i) => {
      const fraction = (i + 1) / (spec.reviewRatings.length + 1);
      const reviewTime = new Date(
        learnedAt.getTime() + fraction * (now_ - learnedAt.getTime())
      );
      const result = schedule(card, rating, reviewTime, DEFAULT_SETTINGS);
      logs.push({
        id: uid("rev"),
        memoryId,
        rating,
        state: result.card.state,
        due: result.card.due,
        stability: result.card.stability,
        difficulty: result.card.difficulty,
        elapsedDays: result.logPreview.elapsedDays,
        lastElapsedDays: result.logPreview.lastElapsedDays,
        scheduledDays: result.logPreview.scheduledDays,
        reviewedAt: reviewTime.toISOString(),
        reviewAhead: false,
      });
      card = result.card;
    });

    const createdAt = learnedAt.toISOString();
    memories.push({
      id: memoryId,
      content: spec.content,
      prompt: spec.prompt,
      answer: spec.answer,
      tags: spec.tags,
      collection: spec.collection || undefined,
      type: undefined,
      createdAt,
      learnedAt: createdAt,
      updatedAt: new Date().toISOString(),
      completed: false,
      archived: false,
      deleted: false,
      card,
    });
  }

  await dbPutMany(STORES.memories, memories);
  await dbPutMany(STORES.reviewLog, logs);

  const collectionNames = Array.from(
    new Set(memories.map((m) => m.collection).filter((c): c is string => !!c))
  );
  for (const name of collectionNames) {
    await ensureCollection(name);
  }
}
